/** Consume the link and activate its membership together, including rejoins. */
export async function acceptInvitedMember(
  invitation: Invitation,
  userId: UserId,
  at: IsoTimestamp,
): Promise<{ member: Member; joined: boolean }> {
  return getDb().transaction((tx) => {
    const accepted = tx.update(invitations)
      .set({ acceptedAt: at, updatedAt: at })
      .where(and(
        orgPredicate(invitations.orgId, invitation.orgId),
        eq(invitations.id, invitation.id),
        isNull(invitations.acceptedAt),
        isNull(invitations.revokedAt),
        gt(invitations.expiresAt, at),
      ))
      .returning().get();
    if (!accepted) throw new Error("That invitation is no longer pending");

    const existing = tx.select().from(members)
      .where(and(orgPredicate(members.orgId, invitation.orgId), eq(members.userId, userId)))
      .get();
    if (existing && existing.archivedAt === null && existing.status === "active") {
      return { member: toMember(existing), joined: false };
    }

    const membership = {
      role: invitation.role,
      status: "active" as const,
      invitedBy: invitation.invitedBy,
      joinedAt: at,
      archivedAt: null,
      updatedAt: at,
    };
    const row = existing
      ? tx.update(members).set(membership)
        .where(and(orgPredicate(members.orgId, invitation.orgId), eq(members.id, existing.id)))
        .returning().get()
      : tx.insert(members).values({
        ...membership, id: newId(), orgId: invitation.orgId, userId,
        lastSeenAt: null, createdAt: at,
      }).returning().get();
    if (!row) throw new Error("Membership could not be activated");
    return { member: toMember(row), joined: true };
  });
}

