import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { formatRelative } from "@/lib/date";
import { can } from "@/lib/permissions";
import type { InvitationId } from "@/types/common";
import type { Actor, Invitation } from "@/types/member";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { RoleBadge } from "../permission/role-badge";

export type InvitationListProps = {
  invitations: readonly Invitation[];
  actor: Actor;
  onRevoke: (invitationId: InvitationId) => void;
  onResend?: (invitationId: InvitationId) => void;
};

/** Neither accepted nor revoked, and not past its expiry. */
export function isPending(invitation: Invitation, now = new Date()): boolean {
  return (
    invitation.acceptedAt === null &&
    invitation.revokedAt === null &&
    new Date(invitation.expiresAt).getTime() > now.getTime()
  );
}

export function InvitationList(
  props: InvitationListProps,
): ReactElement | null {
  const { invitations, actor, onRevoke, onResend } = props;

  // Revoking an invitation is the same grant as issuing one.
  const mayManage = can(
    actor,
    "member:invite",
    organizationResource(actor.orgId),
  );

  const pending = invitations.filter((invitation) => isPending(invitation));
  if (pending.length === 0) {
    return (
      <EmptyState
        title="No pending invitations"
        description="Invitations you send appear here until they are accepted."
      />
    );
  }

  return (
    <Table caption="Pending invitations">
      <TableHead>
        <TableRow>
          <TableHeaderCell>Email</TableHeaderCell>
          <TableHeaderCell>Role</TableHeaderCell>
          <TableHeaderCell>Expires</TableHeaderCell>
          <TableHeaderCell></TableHeaderCell>
        </TableRow>
      </TableHead>
      <TableBody>
        {pending.map((invitation) => (
          <TableRow key={invitation.id}>
            <TableCell>{invitation.email}</TableCell>
            <TableCell className="w-32">
              <RoleBadge role={invitation.role} />
            </TableCell>
            <TableCell className="w-40 text-sm text-neutral-500">
              <Badge tone="neutral" size="sm">
                {formatRelative(invitation.expiresAt)}
              </Badge>
            </TableCell>
            <TableCell className="w-52 text-right">
              {mayManage ? (
                <span className="flex justify-end gap-1">
                  {onResend !== undefined ? (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => onResend(invitation.id)}
                    >
                      Resend
                    </Button>
                  ) : null}
                  <Button
                    variant="danger"
                    size="sm"
                    onClick={() => onRevoke(invitation.id)}
                  >
                    Revoke
                  </Button>
                </span>
              ) : null}
            </TableCell>
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}
/**
 * Renders react-email templates and 'sends' them by writing the draft to the log. No network egress.
 */
import { createLogger } from "@/lib/logger";

export type OutgoingEmail = {
  to: string;
  subject: string;
  html: string;
  text: string;
};

export type RenderedEmail = { subject: string; html: string; text: string };

export type EmailTemplate =
  | "invite"
  | "digest"
  | "mention"
  | "invoice"
  | "welcome"
  | "password-reset"
  | "overdue";

const logger = createLogger("email-service");

/** Subject lines per template; the props fill in the bracketed parts. */
const SUBJECTS: Readonly<Record<EmailTemplate, string>> = {
  invite: "You have been invited to a Taskflow workspace",
  digest: "Your Taskflow digest",
  mention: "You were mentioned in Taskflow",
  invoice: "Your Taskflow invoice",
  welcome: "Welcome to Taskflow",
  "password-reset": "Reset your Taskflow password",
  overdue: "You have overdue issues",
};

/**
 * "Sends" a message. Taskflow has no outbound mail transport by design — the
 * corpus must build and run offline — so delivery means writing the draft to
 * the structured log, where the dev tools tab surfaces it.
 */
export async function sendEmail(message: OutgoingEmail): Promise<void> {
  logger.info("email.sent", {
    to: message.to,
    subject: message.subject,
    bytes: message.html.length,
  });
}

/**
 * Renders a template to both an HTML and a plain-text body. The text half is
 * derived from the HTML rather than written twice, so the two can never drift.
 */
export async function renderEmail(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): Promise<RenderedEmail> {
  const subject = subjectFor(template, props);
  const html = renderBody(template, props);

  return { subject, html, text: toPlainText(html) };
}

function subjectFor(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const base = SUBJECTS[template];
  const orgName = props.orgName;
  return typeof orgName === "string" ? `${base} — ${orgName}` : base;
}

function renderBody(
  template: EmailTemplate,
  props: Readonly<Record<string, unknown>>,
): string {
  const rows = Object.entries(props)
    .filter(([, value]) => value !== null && value !== undefined)
    .map(
      ([key, value]) =>
        `<tr><td>${escapeHtml(key)}</td><td>${escapeHtml(String(value))}</td></tr>`,
    )
    .join("");

  return [
    `<html><body><h1>${escapeHtml(SUBJECTS[template])}</h1>`,
    `<table>${rows}</table>`,
    "</body></html>",
  ].join("");
}

function toPlainText(html: string): string {
  return html
    .replace(/<\/(?:tr|h1|p|div)>/g, "\n")
    .replace(/<[^>]+>/g, " ")
    .replace(/[ \t]+/g, " ")
    .replace(/\n\s+/g, "\n")
    .trim();
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}
/**
 * Validated environment access. Nothing else in Taskflow reads `process.env`
 * — call sites import `env` (or `loadEnv()` when they need to validate a
 * different source, as the tests do) so a missing or malformed variable fails
 * once, loudly, instead of surfacing as `undefined` deep in a request.
 */
import { SITE_CONFIG } from "./site";

export type AppEnv = {
  nodeEnv: "development" | "test" | "production";
  databasePath: string;
  appUrl: string;
  digestEnabled: boolean;
};

const NODE_ENVS = ["development", "test", "production"] as const;

type NodeEnvValue = (typeof NODE_ENVS)[number];

function readNodeEnv(raw: string | undefined): NodeEnvValue {
  const value = (raw ?? "development").trim();
  const match = NODE_ENVS.find((candidate) => candidate === value);
  return match ?? "development";
}

/** Accepts `1`/`true`/`yes`/`on` (case-insensitive) as true; anything else false. */
function readBoolean(raw: string | undefined, fallback: boolean): boolean {
  if (raw === undefined || raw.trim() === "") return fallback;
  const value = raw.trim().toLowerCase();
  if (["1", "true", "yes", "on"].includes(value)) return true;
  if (["0", "false", "no", "off"].includes(value)) return false;
  throw new Error(`Invalid boolean environment value: "${raw}"`);
}

function readUrl(raw: string | undefined, fallback: string): string {
  const value = (raw ?? "").trim() || fallback;
  try {
    // Normalises away a trailing slash so `${appUrl}${path}` never doubles up.
    const parsed = new URL(value);
    return parsed.origin + parsed.pathname.replace(/\/$/, "");
  } catch {
    throw new Error(`Invalid TASKFLOW_APP_URL: "${value}"`);
  }
}

/**
 * Reads and validates the environment. Defaults are chosen so a fresh
 * checkout runs with no `.env` at all — the corpus must build offline.
 */
export function loadEnv(source: NodeJS.ProcessEnv = process.env): AppEnv {
  const nodeEnv = readNodeEnv(source.NODE_ENV);
  const databasePath =
    (source.TASKFLOW_DB_PATH ?? "").trim() ||
    (nodeEnv === "test" ? ":memory:" : "./data/taskflow.db");

  return {
    nodeEnv,
    databasePath,
    appUrl: readUrl(source.TASKFLOW_APP_URL, SITE_CONFIG.url),
    digestEnabled: readBoolean(source.TASKFLOW_DIGEST_ENABLED, nodeEnv !== "test"),
  };
}

export const env: AppEnv = loadEnv();
/**
 * Token-bucket limiter applied to invites, comments, search and password
 * resets.
 *
 * Buckets are keyed by `(orgId, bucketKey)` and held in process — Taskflow
 * runs single-writer, and the corpus has no external cache. Capacity scales
 * with the org's plan through `getPlanLimits()`, so a growth org is not held
 * to a free org's ceiling; the per-bucket shape below is the base rate.
 */
import { getPlanLimits } from "@/config/plan-limits";
import type { PlanId } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

export type RateLimitVerdict = {
  allowed: boolean;
  remaining: number;
  resetAt: IsoTimestamp;
};

export type RateLimitConfig = { capacity: number; refillPerMinute: number };

export const RATE_LIMIT_BUCKETS: Readonly<Record<string, RateLimitConfig>> = {
  "member:invite": { capacity: 20, refillPerMinute: 2 },
  "comment:create": { capacity: 60, refillPerMinute: 20 },
  "issue:create": { capacity: 60, refillPerMinute: 20 },
  "search:query": { capacity: 120, refillPerMinute: 60 },
  "auth:password-reset": { capacity: 5, refillPerMinute: 1 },
  "webhook:deliver": { capacity: 100, refillPerMinute: 50 },
};

/** Applied to any key not in the table above. */
const DEFAULT_BUCKET: RateLimitConfig = { capacity: 30, refillPerMinute: 10 };

type BucketState = { tokens: number; updatedAt: number };

const buckets = new Map<string, BucketState>();

/** Plan-aware org context; services set this when they know the org's plan. */
const planByOrg = new Map<OrgId, PlanId>();

/** Records an org's plan so subsequent bucket sizes scale with its quota. */
export function setOrgPlan(orgId: OrgId, plan: PlanId): void {
  planByOrg.set(orgId, plan);
}

export function getBucketConfig(bucketKey: string): RateLimitConfig {
  return RATE_LIMIT_BUCKETS[bucketKey] ?? DEFAULT_BUCKET;
}

/**
 * Scales the base bucket by the org's hourly API allowance, so the limiter
 * and the plan catalogue can never drift apart: the plan is the source of
 * the ceiling, this table only sets the relative shape.
 */
function configFor(orgId: OrgId, bucketKey: string): RateLimitConfig {
  const base = getBucketConfig(bucketKey);
  const plan = planByOrg.get(orgId) ?? "free";
  const hourly = getPlanLimits(plan).apiRequestsPerHour;
  const factor = Number.isFinite(hourly) ? Math.max(1, hourly / 100) : 100;

  return {
    capacity: Math.min(base.capacity * factor, base.capacity * 100),
    refillPerMinute: Math.min(
      base.refillPerMinute * factor,
      base.refillPerMinute * 100,
    ),
  };
}

/**
 * Spends `cost` tokens from the bucket, refilling first for the elapsed time.
 * Async because the production limiter is expected to move behind a store —
 * every call site already awaits it.
 */
export async function consumeRateLimit(
  orgId: OrgId,
  bucketKey: string,
  cost = 1,
): Promise<RateLimitVerdict> {
  const config = configFor(orgId, bucketKey);
  const key = `${orgId}:${bucketKey}`;
  const nowMs = Date.now();

  const state = buckets.get(key) ?? { tokens: config.capacity, updatedAt: nowMs };
  const elapsedMinutes = (nowMs - state.updatedAt) / 60_000;
  const tokens = Math.min(
    config.capacity,
    state.tokens + elapsedMinutes * config.refillPerMinute,
  );

  const allowed = tokens >= cost;
  const remaining = allowed ? tokens - cost : tokens;
  buckets.set(key, { tokens: remaining, updatedAt: nowMs });

  const deficit = allowed ? config.capacity - remaining : cost - remaining;
  const minutesToReset =
    config.refillPerMinute > 0 ? Math.max(0, deficit) / config.refillPerMinute : 0;

  return {
    allowed,
    remaining: Math.floor(remaining),
    resetAt: toIsoTimestamp(new Date(nowMs + minutesToReset * 60_000)),
  };
}

/** Test-only: drops every bucket and org plan association. */
export function resetRateLimits(): void {
  buckets.clear();
  planByOrg.clear();
}

